"""Copy web/index.html into the firmware as index_html.h. Run after editing the page."""

from pathlib import Path

root = Path(__file__).resolve().parent.parent
html = (root / "web" / "index.html").read_text(encoding="utf-8")
if ')HTML"' in html:
    raise SystemExit('index.html must not contain the text )HTML"')
out = root / "firmware" / "smart_socket" / "index_html.h"
out.write_text(
    "// Generated by tools/embed_html.py from web/index.html. Do not edit.\n"
    "#pragma once\n#include <pgmspace.h>\n\n"
    'const char INDEX_HTML[] PROGMEM = R"HTML(' + html + ')HTML";\n',
    encoding="utf-8", newline="\n")
print(f"wrote {out} ({len(html)} characters)")
